limitrows=[(7,(2*x*x-7)/(5*x*x+x-3),S.oo,r'\frac{2-7/x^2}{5+1/x-3/x^2}'),(8,S.sqrt((9*x**3+8*x-4)/(3-5*x+x**3)),S.oo,r'\sqrt{\frac{9+8/x^2-4/x^3}{1-5/x^2+3/x^3}}'),(9,(4*x+3)/(5*x-1),S.oo,r'\frac{4+3/x}{5-1/x}'),(10,-2/(3*x+7),S.oo,r'\frac{-2/x}{3+7/x}'),(11,(3*x*x+x)/(x**3-4*x+1),-S.oo,r'\frac{3/x+1/x^2}{1-4/x^2+1/x^3}'),(12,(6*x*x+x-5)/(9-2*x*x),-S.oo,r'\frac{6+1/x-5/x^2}{9/x^2-2}'),(13,(x-x**3)/(2-x*x+3*x**3),S.oo,r'\frac{1/x^2-1}{2/x^3-1/x+3}'),(14,(3*x**3-8*x+2)/(4*x**3-5*x*x-2),S.oo,r'\frac{3-8/x^2+2/x^3}{4-5/x-2/x^3}'),(15,(4-S.sqrt(x))/(2+S.sqrt(x)),S.oo,r'\frac{4/\sqrt x-1}{2/\sqrt x+1}'),(16,(x*x+1)*(2*x*x-1)/(x*x+2)**2,-S.oo,r'\frac{(1+1/x^2)(2-1/x^2)}{(1+2/x^2)^2}'),(17,S.sqrt(x+3*x*x)/(4*x-1),S.oo,r'\frac{\sqrt{3+1/x}}{4-1/x}\quad(x>0)'),(18,(x+3)/S.sqrt(2*x*x-1),S.oo,r'\frac{1+3/x}{\sqrt{2-1/x^2}}\quad(x>0)'),(19,S.sqrt(1+4*x**6)/(2-x**3),S.oo,r'\frac{\sqrt{4+1/x^6}}{2/x^3-1}\quad(x>0)'),(20,S.sqrt(1+4*x**6)/(2-x**3),-S.oo,r'\frac{-\sqrt{4+1/x^6}}{2/x^3-1}\quad(x<0)'),(21,(2*x**5-x)/(x**4+3),-S.oo,r'x\frac{2-1/x^4}{1+3/x^4}'),(22,(x**3+6*x-4)/(4*x*x-3*x+3),S.oo,r'x\frac{1+6/x^2-4/x^3}{4-3/x+3/x^2}'),(24,(1+x**6)/(x**4+1),-S.oo,r'x^2\frac{1+1/x^6}{1+1/x^4}'),(25,S.sqrt(25*x*x+2)-5*x,S.oo,r'\frac2{\sqrt{25x^2+2}+5x}'),(26,S.sqrt(4*x*x+3*x)+2*x,-S.oo,r'\frac{3x}{\sqrt{4x^2+3x}-2x}=\frac3{-\sqrt{4+3/x}-2}'),(28,x-S.sqrt(x),S.oo,r'x(1-1/\sqrt x)'),(29,x*x+2*x**7,-S.oo,r'x^7(2+1/x^5)'),(30,S.sin(x)**2/(x*x+1),S.oo,r'0\le\frac{\sin^2x}{x^2+1}\le\frac1{x^2+1}\to0'),(31,x*S.sin(1/x),S.oo,r'\frac{\sin(1/x)}{1/x}\to1'),(32,S.sqrt(x)*S.sin(1/x),S.oo,r'\frac1{\sqrt x}\frac{\sin(1/x)}{1/x}\to0')]
