calc(42,r'f(x)=\sqrt{2x^2+1}/(3x-5)','(a) 그래프에서 점근선 개수와 양끝 극한 (b) 표로 근삿값 (c) 정확한 극한을 구하라.','Find (a) the asymptote counts and tail limits graphically, (b) numerical estimates from a table, and (c) exact limits.',[r'\sqrt{2x^2+1}=|x|\sqrt{2+1/x^2}',r'x\to\infty:\quad f\to\sqrt2/3;\quad x\to-\infty:\quad f\to-\sqrt2/3']+[rf'f({v})={float(f42(mp.mpf(v))):.9f}'for v in [-100000,-1000,1000,100000]]+[r'3x-5=0\Rightarrow x=5/3,\quad\sqrt{2x^2+1}>0'],r'\text{One vertical: }x=5/3;\quad\text{two horizontal: }y=\pm\sqrt2/3','좌우에서 제곱근의 절댓값 부호가 달라진다. 양끝 극한은 크기는 같지만 부호가 반대이다.','The absolute-value factor from the square root changes sign relative to x. The limits have equal magnitudes and opposite signs.',sub='abc');plot(42,[('Two different horizontal tails',[('f',f42,[5/3])],[-20,20],[-3,3])])
calc(43,r'P(x)=a_mx^m+\cdots,\quad Q(x)=b_nx^n+\cdots,\quad a_mb_n\ne0','분자 다항식 차수가 (a) 더 작을 때 (b) 더 클 때 양의 무한대에서 비의 극한을 구하라.','Find the ratio limit at positive infinity when the numerator degree is (a) lower or (b) higher.',[r'P(x)/Q(x)=x^{m-n}\frac{a_m+O(1/x)}{b_n+O(1/x)}',r'm<n:\quad x^{m-n}\to0;\quad m>n:\quad x^{m-n}\to\infty'],r'\text{(a)}\ 0;\quad\text{(b)}\ \begin{cases}\infty&a_m/b_n>0\\-\infty&a_m/b_n<0\end{cases}',sub='ab')
calc(44,r'y=x^n,\quad n\in\mathbb Z','영 지수, 양의 홀수·짝수, 음의 홀수·짝수의 다섯 그래프 유형을 그리고 (a,b) 영의 좌우 (c,d) 양·음 무한대 극한을 정리하라.','Sketch the five exponent types—zero, positive odd/even, negative odd/even—and list limits (a,b) at zero from either side and (c,d) at either infinity.',[r'\text{Column order: }(0^+,0^-,+\infty,-\infty)',r'n=0:\ (1,1,1,1)',r'n>0\text{ odd}:\ (0,0,\infty,-\infty)',r'n>0\text{ even}:\ (0,0,\infty,\infty)',r'n<0\text{ odd}:\ (\infty,-\infty,0,0)',r'n<0\text{ even}:\ (\infty,\infty,0,0)'],r'\text{The five limit rows above give all four requested directions.}',sub='abcd')
plot(44,[('Five integer-power types',[(f'x^{n}',lambda z,n=n:z**n,[0]if n<0 else[])for n in [0,3,2,-1,-2]],[-2,2],[-5,5])])
calc(45,r'\lim_{x\to\pm\infty}f(x)=0,\quad\lim_{x\to0}f(x)=-\infty,\quad f(2)=0,\quad\lim_{x\to3^-}f(x)=\infty,\quad\lim_{x\to3^+}f(x)=-\infty','모든 조건을 만족하는 함수식을 하나 구성하라.','Construct one formula satisfying all conditions.',[r'f(x)=\frac{2-x}{x^2(x-3)}',r'x\to0:\quad f\sim-2/(3x^2);\quad x\to3:\quad f\sim-1/[9(x-3)]',r'\deg\text{ numerator}<\deg\text{ denominator};\quad f(2)=0'],r'f(x)=(2-x)/[x^2(x-3)]')
calc(46,r'x=1,3\text{ vertical asymptotes};\quad y=1\text{ horizontal asymptote}','조건에 맞는 함수식을 하나 구성하라.','Construct a function with the specified asymptotes.',[r'f(x)=1+\frac1{(x-1)(x-3)}',r'x\to\pm\infty:\quad f\to1;\quad x\to1,3:\quad\text{uncancelled simple poles}'],r'f(x)=1+1/[(x-1)(x-3)]')
calc(47,r'f=P_2/Q_2,\quad x=4\text{ vertical asymptote},\quad x=1\text{ only zero},\quad x=-1\text{ removable hole},\quad\lim_{x\to-1}f(x)=2','(a) 원점의 값 (b) 양의 무한대 극한을 구하라.','Find (a) the value at zero and (b) the limit at positive infinity.',[r'f(x)=A\frac{(x-1)(x+1)}{(x-4)(x+1)}\quad(x\ne-1,4)',r'\lim_{x\to-1}f(x)=2A/5=2\Rightarrow A=5',r'f(0)=5/4,\quad\lim_{x\to\infty}f(x)=5'],r'\text{(a)}\ 5/4;\quad\text{(b)}\ 5',sub='ab')
shape=[(48,(1+2*x*x)/(1+x*x),r'\text{Increasing }(0,\infty);\quad\text{decreasing }(-\infty,0)',r'\text{Concave up }(-1/\sqrt3,1/\sqrt3);\quad\text{down outside}',r'y=2;\quad\min(0,1);\quad\text{inflections }(\pm1/\sqrt3,5/4)',[-4,4],[.8,2.2],[]),(49,(1-x)/(1+x),r'\text{Decreasing on }(-\infty,-1),(-1,\infty)',r'\text{Concave down }(-\infty,-1);\quad\text{up }(-1,\infty)',r'y=-1,\ x=-1;\quad(0,1),(1,0)\text{ intercepts}',[-6,6],[-6,6],[-1]),(50,x/S.sqrt(x*x+1),r'\text{Increasing on }\mathbb R',r'\text{Concave up }(-\infty,0);\quad\text{down }(0,\infty)',r'y=-1\text{ on left},\ y=1\text{ on right};\quad(0,0)\text{ inflection}',[-5,5],[-1.2,1.2],[]),(51,x/(x*x+1),r'\text{Increasing }(-1,1);\quad\text{decreasing }(-\infty,-1),(1,\infty)',r'\text{Concave up }(-\sqrt3,0),(\sqrt3,\infty);\quad\text{down }(-\infty,-\sqrt3),(0,\sqrt3)',r'y=0;\quad\min(-1,-1/2),\ \max(1,1/2);\quad\text{inflections }(-\sqrt3,-\sqrt3/4),(0,0),(\sqrt3,\sqrt3/4)',[-5,5],[-.6,.6],[])]
for q,f,monotone,concave,ans,xlim,ylim,breaks in shape:
 calc(q,'y='+S.latex(f),'수평 점근선과 증가·감소, 오목성을 구하여 그래프를 그려라.','Find horizontal asymptotes, monotonicity, and concavity, then sketch the graph.',[rf'f^{{\prime}}={S.latex(S.factor(S.diff(f,x)))},\quad f^{{\prime\prime}}={S.latex(S.factor(S.diff(f,x,2)))}',monotone,concave],ans);plot(q,[('Derivative-guided curve',[('f',S.lambdify(x,f,'math'),breaks)],xlim,ylim)])
polys=[(52,2*x**3-x**4,[-1,3],[-10,3]),(53,x**4-x**6,[-1.5,1.5],[-7,.3]),(54,x**3*(x+2)**2*(x-1),[-2.7,1.5],[-10,15]),(55,(3-x)*(1+x)**2*(1-x)**4,[-2,3.5],[-30,50]),(56,x*x*(x*x-1)**2*(x+2),[-2.5,1.5],[-20,20])]
for q,f,xlim,ylim in polys:
 roots=S.roots(f,x);deg=S.degree(f,x);lc=S.LC(S.Poly(f,x));lp=S.limit(f,x,S.oo);lm=S.limit(f,x,-S.oo)
 calc(q,'y='+S.latex(f),'양끝 극한과 축 교점을 구하고 중근에서 접함 또는 가로지름을 구분하여 개략도를 그려라.','Find tail limits and intercepts, distinguish touching from crossing at multiple zeros, and sketch the curve.',[rf'f(x)\sim {S.latex(lc*x**deg)}\quad(|x|\to\infty)',r'\text{Zeros with multiplicities: }'+r',\quad '.join(rf'{S.latex(z)}\ (m={m})'for z,m in roots.items()),r'\text{Even multiplicity touches; odd multiplicity crosses.}',rf'f(0)={S.latex(f.subs(x,0))}'],rf'\lim_{{x\to\infty}}f={S.latex(lp)},\quad\lim_{{x\to-\infty}}f={S.latex(lm)}');plot(q,[('Tail and intercept sketch',[('f',S.lambdify(x,f,'math'),[])],xlim,ylim)])
f57=lambda z:-4*math.exp(z+2)if z<=-2 else 2*z if z<2 else 2+2*math.exp(2-z)
calc(57,r'f(2)=4,\quad f(-2)=-4,\quad\lim_{x\to-\infty}f(x)=0,\quad\lim_{x\to\infty}f(x)=2','조건을 만족하는 그래프를 구성하라.','Construct a graph satisfying these conditions.',[r'f(x)=\begin{cases}-4e^{x+2}&x\le-2\\2x&-2<x<2\\2+2e^{2-x}&x\ge2\end{cases}',r'f(-2)=-4,\quad f(2)=4;\quad e^{x+2}\to0\ (x\to-\infty),\quad e^{2-x}\to0\ (x\to\infty)'],r'\text{The displayed piecewise function supplies one valid sketch.}');plot(57,[('One valid construction',[('f',f57,[])],[-8,8],[-4.5,4.5])])
f58=x-1/(x+2)+1/(x-2)**2
calc(58,r'\lim_{x\to-\infty}f=-\infty,\quad\lim_{x\to-2^-}f=\infty,\quad\lim_{x\to-2^+}f=-\infty,\quad\lim_{x\to2}f=\infty,\quad\lim_{x\to\infty}f=\infty','조건을 만족하는 그래프를 구성하라.','Construct a graph satisfying all the stated limits.',[r'f(x)=x-1/(x+2)+1/(x-2)^2',r'x\to-2:\ -1/(x+2)\text{ determines the signed divergence}',r'x\to2:\ (x-2)^{-2}\to\infty;\quad f(x)-x\to0\ (x\to\pm\infty)'],r'f(x)=x-1/(x+2)+1/(x-2)^2');plot(58,[('One valid construction',[('f',S.lambdify(x,f58,'math'),[-2,2])],[-7,7],[-10,10])])
f59=lambda z:-.5-.25*z*z if abs(z)<=1 else -1+.25*(abs(z)-2)**2 if abs(z)<4 else 1-math.exp(4-abs(z))
calc(59,r'f^{\prime}(2)=0,\ f(2)=-1,\ f^{\prime}(0)=0,\ f(-x)=f(x),\ \lim_{x\to\infty}f=1;\quad f^{\prime}<0\ (0<x<2),\ f^{\prime}>0\ (x>2);\quad f^{\prime\prime}<0\ (0\le x<1\text{ or }x>4),\ f^{\prime\prime}>0\ (1<x<4)','모든 미분 부호와 대칭 조건에 맞는 그래프를 구성하라.','Construct a graph satisfying every derivative-sign and symmetry condition.',[r't=|x|,\quad f(x)=\begin{cases}-1/2-t^2/4&0\le t\le1\\-1+(t-2)^2/4&1<t<4\\1-e^{4-t}&t\ge4\end{cases}',r'x>0:\quad f^{\prime}=\begin{cases}-x/2&x<1\\(x-2)/2&1<x<4\\e^{4-x}&x>4\end{cases}',r'x>0:\quad f^{\prime\prime}=\begin{cases}-1/2&x<1\\1/2&1<x<4\\-e^{4-x}&x>4\end{cases}',r'\text{Values and first derivatives agree at }x=1,4'],r'\text{Even graph with minima }(\pm2,-1),\quad\lim_{x\to\pm\infty}f=1');plot(59,[('Even construction with the required concavity',[('f',f59,[])],[-8,8],[-1.2,1.2])])
f60=lambda z:z*math.exp(-abs(z)/2)
calc(60,r'f^{\prime}(2)=0,\ f^{\prime}(0)=1,\ f(-x)=-f(x),\ \lim_{x\to\infty}f=0;\quad f^{\prime}>0\ (0<x<2),\ f^{\prime}<0\ (x>2);\quad f^{\prime\prime}<0\ (0<x<4),\ f^{\prime\prime}>0\ (x>4)','모든 조건을 만족하는 그래프를 구성하라.','Construct a graph meeting all conditions.',[r'f(x)=xe^{-|x|/2}',r'x>0:\quad f^{\prime}=e^{-x/2}(1-x/2),\quad f^{\prime\prime}=e^{-x/2}(x/4-1)',r'f^{\prime}(0)=\lim_{h\to0}e^{-|h|/2}=1',r'xe^{-|x|/2}\to0\quad(x\to\pm\infty)'],r'f(x)=xe^{-|x|/2}');plot(60,[('Odd construction with the required turning points',[('f',f60,[])],[-12,12],[-.9,.9])])
f61=lambda z:-z+1/z if z<0 else 2-1/z-1/(2-z)if z<2 else 1/(z-2)
calc(61,r'f(1)=f^{\prime}(1)=0,\ \lim_{x\to2^+}f=\infty,\ \lim_{x\to2^-}f=-\infty,\ \lim_{x\to0}f=-\infty,\ \lim_{x\to-\infty}f=\infty,\ \lim_{x\to\infty}f=0;\quad f^{\prime\prime}>0\ (x>2),\ f^{\prime\prime}<0\ (x<0\text{ or }0<x<2)','주어진 극한과 오목성에 맞는 그래프를 구성하라.','Construct a graph with all the specified limits and concavity.',[r'f(x)=\begin{cases}-x+1/x&x<0\\2-1/x-1/(2-x)&0<x<2\\1/(x-2)&x>2\end{cases}',r'f^{\prime\prime}(x)=\begin{cases}2/x^3&x<0\\-2/x^3-2/(2-x)^3&0<x<2\\2/(x-2)^3&x>2\end{cases}',r'f(1)=2-1-1=0,\quad f^{\prime}(1)=1-1=0'],r'\text{The displayed three-branch function satisfies every condition.}');plot(61,[('Three-branch construction',[('f',f61,[0,2])],[-6,8],[-8,8])])
f62=lambda z:math.sqrt(-z)if z<0 else math.sqrt(z)-z
calc(62,r'g(0)=0,\quad g^{\prime\prime}(x)<0\ (x\ne0),\quad\lim_{x\to-\infty}g=\infty,\quad\lim_{x\to\infty}g=-\infty,\quad\lim_{x\to0^-}g^{\prime}=-\infty,\quad\lim_{x\to0^+}g^{\prime}=\infty','조건을 만족하는 뾰족점 그래프를 구성하라.','Construct a cusped graph meeting these conditions.',[r'g(x)=\begin{cases}\sqrt{-x}&x<0\\\sqrt x-x&x\ge0\end{cases}',r'g^{\prime}(x)=\begin{cases}-1/(2\sqrt{-x})&x<0\\1/(2\sqrt x)-1&x>0\end{cases}',r'g^{\prime\prime}(x)=-1/(4|x|^{3/2})<0\quad(x\ne0)'],r'\text{The displayed piecewise function has a cusp at }(0,0)');plot(62,[('Concave branches meeting at a cusp',[('g',f62,[])],[-5,5],[-3,3])])
calc(63,r'f(x)=\sin x/x,\quad x\ne0','(a) 샌드위치 정리로 양의 무한대 극한 (b) 그래프로 수평 점근선과의 교차 횟수를 구하라.','Find (a) the limit at positive infinity using the squeeze theorem and (b) how often the graph crosses its horizontal asymptote.',[r'x>0:\quad-1/x\le\sin x/x\le1/x\Rightarrow\lim_{x\to\infty}f=0',r'\sin x=0\Rightarrow x=n\pi,\quad n\in\mathbb Z\setminus\{0\}',r'\text{The sine changes sign at each nonzero multiple of }\pi'],r'\text{(a)}\ 0;\quad\text{(b)}\ y=0\text{ is crossed infinitely many times}',sub='ab');plot(63,[('Infinitely many asymptote crossings',[('sin(x)/x',lambda z:math.sin(z)/z,[0])],[-25,25],[-.3,1.1])])
calc(64,r'P(x)=3x^5-5x^3+2x,\quad Q(x)=3x^5','(a) 두 지정 화면에서 그래프와 양끝 거동을 비교하고 (b) 양의 무한대에서 비의 극한이 일임을 증명하라.','(a) Compare graphs and tail behavior in the two specified windows and (b) prove that their ratio tends to one at positive infinity.',[r'P/Q=1-5/(3x^2)+2/(3x^4)\to1\quad(x\to\pm\infty)',r'P,Q\to\infty\ (x\to\infty);\quad P,Q\to-\infty\ (x\to-\infty)'],r'\lim_{x\to\infty}P(x)/Q(x)=1','가까운 화면에서는 교점과 굴곡이 다르지만 큰 화면에서는 최고차항이 지배해 꼬리가 비슷해 보인다. 함수의 차이가 영으로 간다는 뜻은 아니다.','The small window reveals different zeros and turning points. In the large window, leading-term dominance makes the tails similar. This does not assert that their difference tends to zero.',sub='ab')
plot(64,[(title,[('P(x)',lambda z:3*z**5-5*z**3+2*z,[]),('Q(x)',lambda z:3*z**5,[])],a,b)for title,a,b in [('Window [-2,2] by [-2,2]',[-2,2],[-2,2]),('Window [-10,10] by [-10000,10000]',[-10,10],[-10000,10000])]])
calc(65,r'(4x-1)/x<f(x)<(4x^2+3x)/x^2\quad(x>5)','양의 무한대 극한을 구하라.','Find the limit at positive infinity.',[r'4-1/x<f(x)<4+3/x',r'\lim_{x\to\infty}(4-1/x)=\lim_{x\to\infty}(4+3/x)=4'],r'\lim_{x\to\infty}f(x)=4')
calc(66,r'V(0)=5000\ \mathrm L,\quad q=25\ \mathrm{L/min},\quad c_{\rm in}=30\ \mathrm{g/L}','처음 순수한 물에 소금물이 들어오고 유출은 없다고 한다. (a) 시간에 따른 농도를 유도하고 (b) 장시간 극한을 구하라.','Brine enters initially pure water with no outflow. (a) Derive the concentration over time and (b) find its long-time limit.',[r'm(t)=30\cdot25t=750t\ \mathrm g,\quad V(t)=5000+25t\ \mathrm L',r'C(t)=750t/(5000+25t)=30t/(200+t)',r'\lim_{t\to\infty}C(t)=\lim30/(1+200/t)=30'],r'\text{(a)}\ C(t)=30t/(200+t)\ \mathrm{g/L};\quad\text{(b)}\ 30\ \mathrm{g/L}',sub='ab')
fn67=lambda z:(3*z*z+1)/(2*z*z+z+1)
calc(67,r'\left|\frac{3x^2+1}{2x^2+x+1}-1.5\right|<0.05','그래프로 모든 더 큰 입력에서 부등식이 성립하는 문턱값을 하나 구하라.','Use a graph to choose a threshold above which the inequality always holds.',[r'x>0:\quad|f(x)-1.5|=\frac{3x+1}{2(2x^2+x+1)}',r'|f(x)-1.5|<0.05\Longleftrightarrow2x^2-29x-9>0',r'x>(29+\sqrt{913})/4\approx14.80397'],r'N=15\text{ is sufficient}');plot(67,[('Error tolerance and a valid threshold',[('|f-1.5|',lambda z:abs(fn67(z)-1.5),[]),('0.05',lambda z:.05,[])],[5,30],[0,.16])])
ff=lambda z:(1-3*z)/math.sqrt(z*z+1)
for q,direction,Ltarget,cut in [(68,r'\infty',-3,'x>N'),(69,r'-\infty',3,'x<-N')]:
 calc(q,rf'\lim_{{x\to{direction}}}\frac{{1-3x}}{{\sqrt{{x^2+1}}}}={Ltarget},\quad\varepsilon=0.1,0.05','두 허용오차에 대해 정의를 만족하는 문턱값을 구하고 그래프로 나타내라.','Find thresholds satisfying the limit definition for both error tolerances and illustrate them graphically.',[r'u=|x|>0,\quad\sqrt{u^2+1}-u=1/(\sqrt{u^2+1}+u)',r'|f(x)-L|\le1/u+3/(2u^2)',r'u>12:\quad1/u+3/(2u^2)<0.09375<0.1',r'u>22:\quad1/u+3/(2u^2)<0.048554<0.05'],r'\varepsilon=0.1:\ x>12;\quad\varepsilon=0.05:\ x>22'if q==68 else r'\varepsilon=0.1:\ x<-12;\quad\varepsilon=0.05:\ x<-22','제시한 값은 최적 문턱일 필요 없이 정의를 만족하는 충분한 값이다.','The thresholds are sufficient values for the definition; they need not be optimal.');plot(q,[('Error in the specified tail',[('|f-L|',lambda z,Ltarget=Ltarget:abs(ff(z)-Ltarget),[]),('0.1',lambda z:.1,[]),('0.05',lambda z:.05,[])],[5,35]if q==68 else[-35,-5],[0,.24])])
calc(70,r'\lim_{x\to\infty}\frac{3x}{\sqrt{x-3}}=\infty,\quad M=100','정의의 높이를 넘게 하는 문턱값을 그래프로 구하라.','Find and graph a threshold beyond which the function exceeds the specified height.',[r'x>3:\quad\sqrt{x-3}<\sqrt x\Rightarrow3x/\sqrt{x-3}>3\sqrt x',r'x>1112>(100/3)^2\Rightarrow3\sqrt x>100'],r'N=1112\text{ is sufficient}');plot(70,[('Eventual height above one hundred',[('3x/sqrt(x-3)',lambda z:3*z/math.sqrt(z-3),[]),('100',lambda z:100,[])],[900,1400],[89,114])])
calc(71,r'f(x)=1/x^2','(a) 값이 영점영영영일보다 작아지는 큰 양의 입력 (b) 영으로의 극한을 정의로 증명하라.','(a) Find large positive inputs giving a value below 0.0001 and (b) prove convergence to zero from the definition.',[r'1/x^2<10^{-4}\Longleftrightarrow |x|>100;\quad x>0\Rightarrow x>100',r'\varepsilon>0:\quad N=1/\sqrt\varepsilon;\quad x>N\Rightarrow|1/x^2-0|<\varepsilon'],r'\text{(a)}\ x>100;\quad\text{(b)}\ N=\varepsilon^{-1/2}',sub='ab')
calc(72,r'f(x)=1/\sqrt x','(a) 값이 영점영영영일보다 작아지는 입력 (b) 영으로의 극한을 정의로 증명하라.','(a) Find inputs giving a value below 0.0001 and (b) prove convergence to zero from the definition.',[r'1/\sqrt x<10^{-4}\Longleftrightarrow x>10^8',r'\varepsilon>0:\quad N=\varepsilon^{-2};\quad x>N\Rightarrow|1/\sqrt x|<\varepsilon'],r'\text{(a)}\ x>10^8;\quad\text{(b)}\ N=\varepsilon^{-2}',sub='ab')
calc(73,r'\lim_{x\to-\infty}1/x=0','음의 무한대 극한의 정의로 증명하라.','Prove the limit using its negative-infinity definition.',[r'\varepsilon>0:\quad A=-1/\varepsilon<0',r'x<A\Rightarrow -x>1/\varepsilon\Rightarrow|1/x|<\varepsilon'],r'\forall\varepsilon>0,\quad x<-1/\varepsilon\Rightarrow|1/x|<\varepsilon')
calc(74,r'\lim_{x\to\infty}x^3=\infty','무한 극한의 정의로 증명하라.','Prove the infinite limit directly from the definition.',[r'M>0:\quad N=M^{1/3}>0',r'x>N\Rightarrow x^3>M'],r'N=M^{1/3}')
